//! Fetch-owned descriptions. Provider definitions are never rewritten here.
use serde_json::{Value,json};

pub fn definitions()->Vec<Value>{
    let string=json!({"type":"string"});
    let properties=vec![
        ("fetch__discover_servers","Automatically reads supported global Claude Code, Codex and OpenCode MCP definitions when config_path is omitted. Optionally supply one absolute config_path to a home folder, a .codex folder (also checks its parent's Claude/OpenCode locations), or one configuration file. Only known filenames are read; folders are not scanned recursively. Requires server-management permission. Returns compatibility, installed flags, installed_server_id references and safe warnings. Installed rows match an existing import's exact source file/name and must be skipped when selecting new installations. This read does not install, start or log in to a server. Review the user's selection before installation.",json!({"config_path":string}),vec![]),
        ("fetch__install_servers","Prepares selected MCP servers in Fetch's private pinned environments, then attempts their normal Restart / Connect operation and leaves successful connections running. Requires server-management permission. Each servers item supplies server_name and exactly one of an absolute config_path, a full literal command, or a supported MCP url. Commands use the existing supported npx/uvx/local-script forms with quoted arguments; shells, operators, substitutions, environment assignments and credential values are unsupported. URLs use Streamable HTTP; documentation URLs are not interpreted. Source imports reuse exact path/name; direct inputs reuse the same name and normalized original definition. Changed names or definitions create separate instances. Returns a pending installation_id; inspect get_installation, then get_servers for runtime/authentication. Direct progress has config_path:null and never echoes the command/URL. Failed items preserve successful preparation; login/connection failure does not undo it. This operation never authenticates automatically or invokes arbitrary tools. Do not resubmit after an uncertain response.",json!({"servers":{"type":"array","minItems":1,"maxItems":256,"items":{"type":"object","properties":{"config_path":string,"command":string,"url":string,"server_name":string},"required":["server_name"],"oneOf":[{"required":["config_path"]},{"required":["command"]},{"required":["url"]}],"additionalProperties":false}}}),vec!["servers"]),
        ("fetch__get_installation","Reads progress for one installation_id in the current Fetch run. Requires server-management permission. A pending response means keep monitoring the same ID; failed items preserve successful installations. Reading a failed operation is a successful read. Retry only failed entries after reviewing their failure.",json!({"installation_id":string}),vec!["installation_id"]),
        ("fetch__get_servers","Reads saved configuration, latest authentication/runtime state, pending changes and aggregate tool execution counts. Requires server-management permission. Optional id filters select exact server IDs; restart_id requires exactly one id and follows that named attempt through success or failure. Reads never start, authenticate or reconnect a server.",json!({"id":{"type":"array","items":string},"restart_id":string}),vec![]),
        ("fetch__list_tools","Lists installed tool definitions and reports unavailable servers or rejected tools. Valid remaining tools stay usable. Omit view to inspect this MCP client's catalog, or choose raw or a supported protocol view. Check complete, origins.status and rejected_tools before assuming every upstream tool is available. Requires catalog permission. Optional server_id filters select exact origins; a read never starts or authenticates a server.",json!({"server_id":{"type":"array","items":string},"view":{"enum":["raw","2025-11-25","2026-07-28"]}}),vec![]),
        ("fetch__authenticate_server","Deprecated compatibility tool. Prefer fetch__restart_server with interactive:true to start/connect and let the server perform its own login. This existing tool remains available: interactive defaults true; false only renews saved remote access and cannot open a browser or launch local setup. It does not expose provider tokens, read native token files or prove account access merely because a local server starts. Manual fixed keys remain native Settings-only. Inspect get_servers for pending status and user handoffs.",json!({"server_id":string,"interactive":{"type":"boolean"}}),vec!["server_id"]),
        ("fetch__update_server_config","Saves Fetch-owned call limits only: max_concurrent_calls, default_timeout_ms and per-tool tool_timeouts_ms. Requires server-management permission and matching catalog permission for each edited tool. Omitted settings stay unchanged; tool_timeouts_ms entries merge and null removes an override. Changes apply to new calls without restarting or authenticating. Server launch configuration, environment, headers and provider credentials cannot be edited through this tool. Manual fixed keys remain native Settings-only. Ask the user to open a supported server folder in native Fetch Settings and use the server’s own setup.",json!({"server_id":string,"execution":{"type":"object","properties":{"max_concurrent_calls":{"type":"integer","minimum":1,"maximum":64},"default_timeout_ms":{"type":"integer","minimum":1,"maximum":86400000},"tool_timeouts_ms":{"type":"object","additionalProperties":{"type":["integer","null"],"minimum":1,"maximum":86400000}}},"additionalProperties":false}}),vec!["server_id"]),
        ("fetch__restart_server","Starts/connects an installed server, or normally restarts/reconnects it. Requires server-management permission. Set interactive:true for an explicit user login attempt: use a recorded native setup helper if present, otherwise the configured local server startup command, or supported remote OAuth. No login command is guessed. Returns authenticating while waiting for user setup; inspect get_servers and relay its user instructions. A supplied sign_in host needs explicit user consent before requesting interactive:true again to open that page. Startup/helper exit alone does not prove account login. Without interactive (default false), restart uses existing drain/force rules and normal readiness limits. A restart_id is pending, not success; inspect get_servers with that ID. force_restart may interrupt work and must not be escalated automatically; it cannot be combined with interactive:true. Manual configuration values remain native Settings-only.",json!({"server_id":string,"force_restart":{"type":"boolean"},"interactive":{"type":"boolean"}}),vec!["server_id"]),
        ("fetch__delete_server","Removes one Fetch-managed MCP server registration. Native server state, existing credential files and keys, and installed packages are preserved. Requires server-management permission for that server. Closes its idle local process or remote connection before removing its registration; original client configurations, original scripts, shared runtimes and other servers are preserved. Active installation, authentication, restart, calls or unresolved outcomes return SERVER_BUSY without force or cancellation. Returns status deleted only after cleanup succeeds; missing/already-deleted servers return SERVER_NOT_FOUND. Cleanup failure may be partial: inspect the failure before deliberately retrying, and never assume an uncertain response deleted the server.",json!({"server_id":string}),vec!["server_id"]),
    ];
    properties.into_iter().map(|(name,description,properties,required)|json!({"name":name,"description":description,"inputSchema":{"type":"object","properties":properties,"required":required,"additionalProperties":false}})).collect()
}
pub fn scope(name:&str)->Option<&'static str>{match name{"fetch__list_tools"=>Some("fetch:catalog"),"fetch__discover_servers"|"fetch__install_servers"|"fetch__get_installation"|"fetch__get_servers"|"fetch__authenticate_server"|"fetch__update_server_config"|"fetch__restart_server"|"fetch__delete_server"=>Some("fetch:manage"),_=>None}}
